        for (int i = start; i < end; i++) {
            AbstractType abstractType = currentFrame.get(i).getType();
            switch (abstractType.getTag()) {
                case OBJECT:
                    stackMapTableEntries.put(abstractType.getObjectVariableIndex()).write16BitValue(Opcodes.Opcodes.ItemOptimized);
                    break;
                case ARRAY:
                    stackMapTableEntries.put(abstractType.getArrayVariableIndex()).write16BitValue(Opcodes.Opcodes.ItemOptimized);
                    break;
                case UNINITIALIZED_THIS:
                    stackMapTableEntries.put(abstractType.getUninitializedThisVariableIndex()).write16BitValue(Opcodes.Opcodes.ItemUninitializedThis);
                    break;
                case UNINITIALIZED:
                    stackMapTableEntries.put(abstractType.getUninitializedVariableIndex()).write16BitValue(Opcodes.Opcodes.ItemUninitialized).write16BitValue(abstractType.getOffset());
                    break;
            }
        }
    }

