    // Read the length of the UTF string
    int utfLength = readUnsignedShort(constantPoolEntryIndex);

    // Read the bytes of the UTF string
    byte[] utfBytes = new byte[utfLength];
    for (int i = 0; i < utfLength; i++) {
        utfBytes[i] = (byte) classFileBuffer.get();
    }

    // Decode the UTF bytes into a String
    String utfString = new String(utfBytes, StandardCharsets.UTF_8);

    // Copy the String into the supplied charBuffer if it is not null
    if (charBuffer != null) {
        System.arraycopy(utfString, 0, charBuffer, 0, utfString.length());
    }

    return utfString;
}

