public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int index = filename.lastIndexOf(".");
    if (index == -1) {
        return -1;
    }

    if (index + 1 < filename.length() && filename.charAt(index + 1) == '/') {
        return -1;
    }

    return index;
}

