    // Calculate the midpoint of the box along the x-axis
    float xMidpoint = box.getSize().x / 2;

    // Calculate the positions of the two resulting boxes along the x-axis
    float x1 = box.getPosition().x;
    float x2 = box.getPosition().x + xMidpoint;

    // Calculate the sizes of the two resulting boxes
    float width1 = xMidpoint;
    float width2 = box.getSize().x - xMidpoint;

    // Create the two resulting boxes
    Box2D box1 = new Box2D(new Vector2(x1, box.getPosition().y), new Vector2(width1, box.getSize().y));
    Box2D box2 = new Box2D(new Vector2(x2, box.getPosition().y), new Vector2(width2, box.getSize().y));

    // Return the pair of resulting boxes
    return new Pair<>(box1, box2);
}

