public static Meteor lookup(HttpServletRequest r) {
    // Determine the user agent string
    String userAgent = r.getHeader("User-Agent");
    if (userAgent == null || userAgent.isEmpty()) {
        return null;
    }

    // Check if the user agent string is a valid meteor ID
    boolean isMeteor = userAgent.matches("^Meteor\\/\\d+\\.\\d+\\.\\d+");
    if (!isMeteor) {
        return null;
    }

    // Extract the meteor ID from the user agent string
    int slashIndex = userAgent.indexOf('/');
    int spaceIndex = userAgent.indexOf(' ');
    String meteorId = userAgent.substring(slashIndex + 1, spaceIndex);

    // Retrieve the meteor instance from the database
    Meteor meteor = MeteorDao.findById(meteorId);

    // Return the meteor instance or null if not found
    return meteor;
}

