    // Check if the int value can fit in 4 bytes
    if (intValue >= -128 && intValue <= 127) {
        // If the int value fits in 1 byte, put it in the first byte
        this.putByte((byte) intValue);
    } else if (intValue >= -32768 && intValue <= 32767) {
        // If the int value fits in 2 bytes, put it in the first 2 bytes
        this.putShort((short) intValue);
    } else if (intValue >= -2147483648 && intValue <= 2147483647) {
        // If the int value fits in 4 bytes, put it in the first 4 bytes
        this.putInt(intValue);
    } else {
        // If the int value doesn't fit in any of the above formats, throw an exception
        throw new IllegalArgumentException("The value does not fit in any of the allowed integer formats");
    }
    return this;
}

